/** @param {{des: object}} api */
export default function tower2({ des, selection, shuffle, luaList }) {
    des.level_init({ style: 'solidfill', fg: ' ' });

    des.level_flags('mazelevel', 'noteleport', 'hardfloor', 'solidify');
    des.map({
        halign: 'half-left', valign: 'center', map: `  --- --- ---  
  |.| |.| |.|  
---S---S---S---
|.S.........S.|
---.------+----
  |......|..|  
--------.------
|.S......+..S.|
---S---S---S---
  |.| |.| |.|  
  --- --- ---  
`,
    });
    // Random places are the 10 niches
    // luaList keeps Lua's 1-based indices, so place[n] means the same here.
    const place = luaList(
        [3, 1], [7, 1], [11, 1], [1, 3], [13, 3], [1, 7], [13, 7], [3, 9], [7, 9], [11, 9]
    );
    shuffle(place);

    des.ladder('up', 11, 5);
    des.ladder('down', 3, 7);
    des.door('locked', 10, 4);
    des.door('locked', 9, 7);
    des.monster('&', place[10]);
    des.monster('&', place[1]);
    des.monster('hell hound pup', place[2]);
    des.monster('hell hound pup', place[3]);
    des.monster('winter wolf', place[4]);
    des.object({
        id: 'chest', coord: place[5],
        contents: () => {
            des.object('amulet of life saving');
        },
    });
    des.object({
        id: 'chest', coord: place[6],
        contents: () => {
            des.object('amulet of strangulation');
        },
    });
    des.object('water walking boots', place[7]);
    des.object('crystal plate mail', place[8]);

    // luaList keeps Lua's 1-based indices, so spbooks[n] means the same here.
    const spbooks = luaList(
        'spellbook of invisibility',
        'spellbook of cone of cold',
        'spellbook of create familiar',
        'spellbook of clairvoyance',
        'spellbook of charm monster',
        'spellbook of stone to flesh',
        'spellbook of polymorph',
    );
    shuffle(spbooks);
    des.object(spbooks[1], place[9]);

    // Walls in the tower are non diggable
    des.non_diggable(selection.area(0, 0, 14, 10));
}
